typedef struct { int id; char* msg; } ThreadArgs;

void* start_routine(void* arg) {
    ThreadArgs* args = (ThreadArgs*)arg;
    // Use args->id, args->msg
    return (void*)0; // Thread exit status
}

pthread_t tid;
pthread_attr_t attr;
ThreadArgs args = {101, "Config"};
struct sched_param param;

// Setup Attributes: Detached state + Priority
pthread_attr_init(&attr);
pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

pthread_attr_getschedparam(&attr, &param);
param.sched_priority = 50;
pthread_attr_setschedparam(&attr, &param);

// Create the thread, passing custom attributes and struct pointer
int status = pthread_create(&tid, &attr, start_routine, &args);

pthread_attr_destroy(&attr);
